using System.IO.Compression;
using System.Xml.Linq;
using HikingGuide.Core.Favorites;
using HikingGuide.Infrastructure.Favorites;
namespace HikingGuide.Infrastructure.Tests;
public class FavoriteTransfer194Tests:IDisposable
{
    private readonly string _root=Path.Combine("F:\\Codex\\Temp","Favorite194",Guid.NewGuid().ToString("N"));
    private static FavoriteMediaInput Image=>new(Convert.FromBase64String("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+j2ioAAAAASUVORK5CYII="),"示例.png","image/png",".png",1,1,Caption:"图片说明",ExternalUrl:"https://example.com/p.png");
    private async Task<FavoritesRepository> Repo(string name){var r=new FavoritesRepository(new FavoritesPathProvider(Path.Combine(_root,name)));await r.InitializeAsync();return r;}
    [Fact]public async Task MultipleCollectionsIncludeEmptyFolderAndExcludeOtherPoints(){var r=await Repo("source");var now=DateTimeOffset.UtcNow;var cs=new List<FavoriteCollection>();for(int i=0;i<3;i++)cs.Add(await r.SaveCollectionAsync(new(Guid.NewGuid(),"收藏夹"+i,i,now,now)));for(int i=0;i<2;i++)await r.SaveAsync(new(){Name="收藏点"+i,CollectionId=cs[i].Id,Latitude=23,Longitude=113},[Image]);var package=Path.Combine(_root,"two.hgfav");await r.ExportAsync(package,collectionIds:[cs[0].Id,cs[2].Id]);var target=await Repo("target");await target.ImportAsync(package);Assert.Single(await target.SearchAsync());Assert.Contains(await target.CollectionsAsync(),c=>c.Name==cs[2].Name);Assert.DoesNotContain(await target.CollectionsAsync(),c=>c.Name==cs[1].Name);var kmz=Path.Combine(_root,"two.kmz");var result=await r.ExportKmzAsync(kmz,collectionIds:[cs[0].Id,cs[2].Id]);Assert.Equal(1,result.PointCount);Assert.Equal(2,result.CollectionCount);}
    [Fact]public async Task KmzRoundTripPreservesPointMediaDescriptionAndConflictPolicy(){var source=await Repo("source");var p=new FavoritePoint{Name="水源",Description="山泉 & <原文> 参考 https://example.com/info",Latitude=23,Longitude=113,ElevationMeters=123.4,SourceReference="https://example.com/guide"};await source.SaveAsync(p,[Image]);var kmz=Path.Combine(_root,"points.kmz");await source.ExportKmzAsync(kmz);var target=await Repo("target");var importer=new FavoriteKmzImporter();Assert.Equal(1,(await importer.ImportAsync(target,kmz)).Imported);var loaded=(await target.GetAsync(p.Id))!;Assert.Equal(p.Description,loaded.Point.Description);Assert.Equal(p.ElevationMeters,loaded.Point.ElevationMeters);Assert.Equal(Image.Bytes,await target.ReadOriginalAsync(loaded.Blobs.Single()));Assert.Single(loaded.Attachments);Assert.Equal(Image.OriginalFileName,loaded.Attachments[0].OriginalFileName);Assert.Equal(Image.Caption,loaded.Attachments[0].Caption);Assert.Equal(Image.ExternalUrl,loaded.Attachments[0].ExternalUrl);Assert.Equal(p.SourceReference,loaded.Point.SourceReference);Assert.Equal(1,(await importer.ImportAsync(target,kmz)).Skipped);Assert.Equal(1,(await importer.ImportAsync(target,kmz,FavoriteConflictPolicy.KeepBoth)).Imported);Assert.Equal(2,(await target.SearchAsync()).Count);}
    [Fact]public async Task UnsafeKmzAndCancellationLeaveExistingLibraryIntact(){var r=await Repo("source");var p=new FavoritePoint{Name="原有点",Latitude=23,Longitude=113};await r.SaveAsync(p);var file=Path.Combine(_root,"unsafe.kmz");using(var z=ZipFile.Open(file,ZipArchiveMode.Create)){using var w=new StreamWriter(z.CreateEntry("../doc.kml").Open());w.Write("<kml/>");}await Assert.ThrowsAsync<InvalidDataException>(()=>new FavoriteKmzImporter().ImportAsync(r,file));using var token=new CancellationTokenSource();token.Cancel();await Assert.ThrowsAnyAsync<OperationCanceledException>(()=>new FavoriteKmzImporter().ImportAsync(r,file,token:token.Token));Assert.Equal(p,(await r.GetAsync(p.Id))!.Point with{ModifiedAt=p.ModifiedAt});Assert.Single(await r.SearchAsync());}
    [Fact]public async Task DownloadedMediaStoresOriginalUrlWithLocalBlob(){var r=await Repo("source");var p=new FavoritePoint{Name="本地图片点",Latitude=23,Longitude=113};await r.SaveAsync(p,[Image]);var d=(await r.GetAsync(p.Id))!;Assert.Equal(Image.ExternalUrl,d.Attachments.Single().ExternalUrl);Assert.False(d.Attachments.Single().OnlineOnly);Assert.Equal(Image.Bytes,await r.ReadOriginalAsync(d.Blobs.Single()));}
    [Fact]public async Task KmzDistinguishesEmbeddedPhotoOriginFromSeparateOnlinePhoto(){var r=await Repo("source");var p=new FavoritePoint{Name="图片组",Latitude=23,Longitude=113};await r.SaveAsync(p,[Image]);var d=(await r.GetAsync(p.Id))!;var online=new FavoriteMediaAttachment(Guid.NewGuid(),p.Id,null,"单独网络图片.jpg","网络图片说明",1,DateTimeOffset.UtcNow,"https://example.com/other.jpg",true);await r.SaveAsync(p,retained:d.Attachments.Concat([online]).ToArray());var file=Path.Combine(_root,"mixed.kmz");await r.ExportKmzAsync(file);var target=await Repo("target");await new FavoriteKmzImporter().ImportAsync(target,file);var imported=(await target.GetAsync(p.Id))!;Assert.Equal(2,imported.Attachments.Count);var reference=Assert.Single(imported.Attachments,a=>a.OnlineOnly);Assert.Equal(online.ExternalUrl,reference.ExternalUrl);Assert.Equal(online.OriginalFileName,reference.OriginalFileName);Assert.Equal(online.Caption,reference.Caption);Assert.Single(imported.Blobs);}
    public void Dispose(){if(Directory.Exists(_root))Directory.Delete(_root,true);}
}
